def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def read_record(repo,record):
    path=(repo/record["path"]).resolve()
    raw=path.read_bytes()
    if len(raw)!=record["bytes"] or digest(raw)!=record["sha256"]:
        raise ValueError("A complete source/proof/parameter parent changed: "+str(path))
    return path,raw


def substitute(text,before,after,count,label):
    if not before or text.count(before)!=count:
        raise ValueError("A complete exact substitution changed its count: "+label)
    return text.replace(before,after)


def serialized(value):
    return (json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+"\n").encode()


def write_complete(outdir,record,raw):
    if len(raw)!=record["bytes"] or digest(raw)!=record["sha256"]:
        raise ValueError("The reproduced whole output differs: "+record["name"])
    path=outdir/record["name"]
    if path.exists():
        if path.read_bytes()!=raw:
            raise ValueError("Do not overwrite a different existing complete output: "+str(path))
    else:
        with path.open("xb") as handle:
            handle.write(raw)
    if path.read_bytes()!=raw:
        raise ValueError("The complete output changed during its write")
    return dict(path=str(path.resolve()),bytes=len(raw),sha256=digest(raw))


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo",type=Path,required=True)
    parser.add_argument("--outdir",type=Path,required=True)
    args=parser.parse_args()
    repo=args.repo.resolve()
    outdir=args.outdir.resolve()
    inputs=[]
    source_path,parent_source=read_record(repo,DATA["parent_source"])
    inputs.append((source_path,parent_source))
    ready_path,parent_ready=read_record(repo,DATA["parent_ready"])
    inputs.append((ready_path,parent_ready))
    for record in DATA["required_source_or_proof_files"]:
        inputs.append(read_record(repo,record))
    for path,_ in inputs:
        if outdir==path or outdir in path.parents:
            raise ValueError("The output namespace cannot contain any consumed original file")
    text=parent_source.decode("utf-8")
    for patch in DATA["source_patches"]:
        text=substitute(text,patch["before"],patch["after"],patch["count"],patch["label"])
    output_source=text.encode("utf-8")
    restored=text
    for patch in reversed(DATA["source_patches"]):
        restored=substitute(restored,patch["after"],patch["before"],patch["count"],
            "inverse "+patch["label"])
    if restored.encode("utf-8")!=parent_source:
        raise ValueError("The full inverse did not recover every original source byte")
    original=json.loads(parent_ready)
    target=json.loads(parent_ready)
    for key,value in DATA["ready_changed_keys"].items():
        target[key]=value
    output_ready=serialized(target)
    reverse=json.loads(output_ready)
    for key in DATA["ready_changed_keys"]:
        if key in original:
            reverse[key]=original[key]
        else:
            del reverse[key]
    if reverse!=original:
        raise ValueError("The complete parameter inverse changed its original object")
    old_step=original["steps"][0]
    new_step=target["steps"][0]
    old_summary=next(iter(old_step["summary"].values()))
    new_summary=next(iter(new_step["summary"].values()))
    if any(new_summary.get(key)!=value for key,value in old_summary.items()):
        raise ValueError("An original complete scalar selector was lost")
    if (len(old_step["args"])!=8 or len(new_step["args"])!=8
            or new_step["args"][-2:]!=["--support-chunk-rows","4096"]):
        raise ValueError("Retain the complete original parameter count and support partition")
    outdir.mkdir(parents=True,exist_ok=True)
    records=[write_complete(outdir,DATA["output_source"],output_source),
        write_complete(outdir,DATA["output_ready"],output_ready)]
    for path,raw in inputs:
        if path.read_bytes()!=raw:
            raise ValueError("A complete original input changed during source construction")
    print(json.dumps(dict(schema=DATA["schema"],complete=True,outputs=records,
        full_source_inverse_recovered=True,full_parameter_inverse_recovered=True,
        original_scalar_selector_count=len(old_summary),
        new_scalar_selector_count=len(new_summary),
        all_original_scalar_selectors_preserved=True,
        Python_AST_or_compile_executed=False,scientific_import_or_execution=False,
        source_construction_only=True,new_solver_gate=False),sort_keys=True))
    return 0


if __name__=="__main__":
    raise SystemExit(main())
